/**
 * Helpers for the generated named queries: request windows, wire formats and the failure a
 * zero-or-one query raises. Regenerated by Dryv; do not edit.
 */
import { HttpException } from "@nestjs/common";
import type { EntityManager } from "typeorm";

export type Row = Record<string, unknown>;

/** Values the access policies provide to a query, keyed by policy id then provided name. */
export type PolicyValues = Record<string, Record<string, unknown> | undefined>;

export interface ReadContext {
  policies?: PolicyValues;
  /** The open transaction to read inside; reads use their own connection when absent. */
  manager?: EntityManager;
}

export interface Page {
  limit: number;
  offset: number;
}

export const DEFAULT_PAGE_LIMIT = 50;

/** A requested window clamped to the query's maximum limit. */
export function pageWindow(limit: unknown, offset: unknown, maxLimit: number): Page {
  const requested = Math.trunc(Number(limit ?? DEFAULT_PAGE_LIMIT)) || DEFAULT_PAGE_LIMIT;
  return {
    limit: Math.min(Math.max(requested, 1), maxLimit),
    offset: Math.max(Math.trunc(Number(offset ?? 0)) || 0, 0),
  };
}

/** A calendar date read by node-pg as local midnight, as `YYYY-MM-DD`. */
export function dateOnly(value: unknown): unknown {
  if (!(value instanceof Date)) return value;
  const month = String(value.getMonth() + 1).padStart(2, "0");
  const day = String(value.getDate()).padStart(2, "0");
  return `${String(value.getFullYear()).padStart(4, "0")}-${month}-${day}`;
}

/** A timestamp as an ISO instant. */
export function instant(value: unknown): unknown {
  return value instanceof Date ? value.toISOString() : value;
}

/** The failure a zero-or-one query raises when nothing matches. */
export function missing(code: string, message: string, status: number): HttpException {
  return new HttpException({ code, message }, status);
}

/** A LIKE pattern matching values that start with `prefix`. */
export function prefixPattern(prefix: unknown): string {
  return `${String(prefix).replace(/[\\%_]/g, "\\$&")}%`;
}
